// Characterization of numeric comparison filters (>, >=, <, <=), recorded
// before they compared numbers without formatting them as text. One line per
// column type and filter: search => indexes of the rows the filter keeps.
import 'package:flutter_test/flutter_test.dart';
import 'package:pluto_grid_plus/pluto_grid_plus.dart';

void main() {
  test('rows kept by numeric comparison filters', () {
    final List<String> actual = <String>[];
    final Map<String, PlutoColumnType Function()> types =
        <String, PlutoColumnType Function()>{
          'number #,###': PlutoColumnType.number,
          'number #,###.0': () =>
              PlutoColumnType.number(format: '#,###.0', locale: 'en'),
          'number de': () =>
              PlutoColumnType.number(format: '#,###.##', locale: 'de'),
          'number !negative': () => PlutoColumnType.number(negative: false),
          'double': PlutoColumnType.double,
          'double de': () => PlutoColumnType.double(locale: 'de'),
          'currency': () => PlutoColumnType.currency(
            locale: 'en_US',
            symbol: r'$',
            decimalDigits: 2,
          ),
        };
    final List<Object?> values = <Object?>[
      0,
      1,
      2,
      -3,
      1000,
      1234,
      1.4,
      1.45,
      1.5,
      -3.5,
      -0.0,
      0.004,
      123456.789,
      1e21,
      1e-7,
      double.nan,
      double.infinity,
      '7',
      '1,234',
      '1.234,5',
      'abc',
      null,
    ];
    final Map<String, PlutoFilterType> filters = <String, PlutoFilterType>{
      'greaterThan': const PlutoFilterTypeGreaterThan(),
      'greaterThanOrEqualTo': const PlutoFilterTypeGreaterThanOrEqualTo(),
      'lessThan': const PlutoFilterTypeLessThan(),
      'lessThanOrEqualTo': const PlutoFilterTypeLessThanOrEqualTo(),
    };
    final List<String> searches = <String>[
      '1',
      '1.4',
      '1,4',
      '-3',
      '1000',
      '1.234',
      '0',
      '',
      'abc',
      '1e3',
    ];
    for (final MapEntry<String, PlutoColumnType Function()> type
        in types.entries) {
      final PlutoColumn column = PlutoColumn(
        title: 'n',
        field: 'n',
        type: type.value(),
      );
      final List<PlutoRow<dynamic>> rows = <PlutoRow<dynamic>>[
        for (final Object? value in values)
          PlutoRow<dynamic>(
            cells: <String, PlutoCell>{'n': PlutoCell(value: value)},
          ),
      ];
      PlutoGridStateManager.initializeRows(<PlutoColumn>[column], rows);
      for (final MapEntry<String, PlutoFilterType> filter in filters.entries) {
        final List<String> results = <String>[];
        for (final String search in searches) {
          final FilteredListFilter<PlutoRow<dynamic>?> keep =
              FilterHelper.convertRowsToFilter(
                <PlutoRow<dynamic>>[
                  FilterHelper.createFilterRow(
                    columnField: 'n',
                    filterType: filter.value,
                    filterValue: search,
                  ),
                ],
                <PlutoColumn>[column],
              )!;
          results.add(
            '$search=>${<int>[for (int i = 0; i < rows.length; i++)
              if (keep(rows[i])) i].join(',')}',
          );
        }
        actual.add('${type.key} | ${filter.key} | ${results.join(' ; ')}');
      }
    }
    expect(actual, _Expected.lines);
  });
}

